<?= view('layout/header', ['title' => 'Sales History']) ?><h1>Sales history</h1><p><a class="button" href="<?= site_url('sales/new') ?>">Record sale</a></p><div class="panel table-wrap"><table><thead><tr><th>ID</th><th>Product</th><th>Customer</th><th>Sold by</th><th>Quantity</th><th>Total</th><th>Date</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><?= esc($item['id']) ?></td><td><?= esc($item['product_name']) ?></td><td><?= esc($item['customer_name'] ?: 'Walk-in') ?></td><td><?= esc($item['staff_name']) ?></td><td><?= esc($item['quantity']) ?></td><td>₱<?= number_format((float)$item['total_price'], 2) ?></td><td><?= esc($item['created_at']) ?></td></tr><?php endforeach ?><?php if (! $items): ?><tr><td colspan="7">No sales yet.</td></tr><?php endif ?></tbody></table></div><?= view('layout/footer') ?>
